{"file_path": "frappe-bench/apps/dialysis_center/dialysis_center/public/src/utils/formatters.js", "initial_content": "/**
 * Dialysis Center - Formatters Utility
 * Functions for formatting dates, currency, numbers, and other data types
 */

import { DATE_FORMATS } from './constants.js';

/**
 * Format date to display format
 * @param {string|Date} date - Date to format
 * @param {boolean} includeTime - Include time in format
 * @returns {string} Formatted date string
 */
export function formatDate(date, includeTime = false) {
	if (!date) return '';

	const dateObj = typeof date === 'string' ? new Date(date) : date;

	if (includeTime) {
		return frappe.datetime.str_to_user(dateObj);
	}

	return frappe.datetime.str_to_user(dateObj.toISOString().split('T')[0]);
}

/**
 * Format datetime to display format with time
 * @param {string|Date} datetime - Datetime to format
 * @returns {string} Formatted datetime string
 */
export function formatDateTime(datetime) {
	if (!datetime) return '';
	return frappe.datetime.str_to_user(datetime);
}

/**
 * Format time only (HH:MM)
 * @param {string|Date} datetime - Datetime to extract time from
 * @returns {string} Formatted time string
 */
export function formatTime(datetime) {
	if (!datetime) return '';
	const dateObj = typeof datetime === 'string' ? new Date(datetime) : datetime;
	return dateObj.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: false });
}

/**
 * Format currency amount
 * @param {number} amount - Amount to format
 * @param {string} currency - Currency code (default from system)
 * @returns {string} Formatted currency string
 */
export function formatCurrency(amount, currency = null) {
	if (amount === null || amount === undefined) return '';

	const cur = currency || frappe.boot.sysdefaults.currency || 'USD';
	return frappe.format(amount, { fieldtype: 'Currency', options: cur });
}

/**
 * Format number with specified decimals
 * @param {number} number - Number to format
 * @param {number} decimals - Number of decimal places
 * @returns {string} Formatted number string
 */
export function formatNumber(number, decimals = 2) {
	if (number === null || number === undefined) return '';
	return parseFloat(number).toFixed(decimals);
}

/**
 * Format percentage
 * @param {number} value - Value to format as percentage
 * @param {number} decimals - Number of decimal places
 * @returns {string} Formatted percentage string
 */
export function formatPercent(value, decimals = 1) {
	if (value === null || value === undefined) return '';
	return `${parseFloat(value).toFixed(decimals)}%`;
}

/**
 * Format duration in minutes to hours:minutes
 * @param {number} minutes - Duration in minutes
 * @returns {string} Formatted duration (e.g., "4h 30m")
 */
export function formatDuration(minutes) {
	if (!minutes) return '0m';

	const hours = Math.floor(minutes / 60);
	const mins = minutes % 60;

	if (hours === 0) return `${mins}m`;
	if (mins === 0) return `${hours}h`;
	return `${hours}h ${mins}m`;
}

/**
 * Format weight with unit
 * @param {number} weight - Weight value
 * @param {string} unit - Unit (default: kg)
 * @returns {string} Formatted weight
 */
export function formatWeight(weight, unit = 'kg') {
	if (weight === null || weight === undefined) return '';
	return `${formatNumber(weight, 1)} ${unit}`;
}

/**
 * Format blood pressure
 * @param {number} systolic - Systolic BP
 * @param {number} diastolic - Diastolic BP
 * @returns {string} Formatted BP (e.g., "120/80 mmHg")
 */
export function formatBloodPressure(systolic, diastolic) {
	if (!systolic || !diastolic) return '';
	return `${systolic}/${diastolic} mmHg`;
}

/**
 * Format temperature
 * @param {number} temp - Temperature value
 * @param {string} unit - Unit (C or F)
 * @returns {string} Formatted temperature
 */
export function formatTemperature(temp, unit = 'C') {
	if (temp === null || temp === undefined) return '';
	return `${formatNumber(temp, 1)}°${unit}`;
}

/**
 * Format phone number
 * @param {string} phone - Phone number
 * @returns {string} Formatted phone number
 */
export function formatPhone(phone) {
	if (!phone) return '';
	// Remove non-numeric characters
	const cleaned = phone.replace(/\D/g, '');

	// Format based on length
	if (cleaned.length === 10) {
		return `(${cleaned.slice(0, 3)}) ${cleaned.slice(3, 6)}-${cleaned.slice(6)}`;
	}
	return phone;
}

/**
 * Truncate text with ellipsis
 * @param {string} text - Text to truncate
 * @param {number} maxLength - Maximum length
 * @returns {string} Truncated text
 */
export function truncateText(text, maxLength = 50) {
	if (!text) return '';
	if (text.length <= maxLength) return text;
	return text.substring(0, maxLength) + '...';
}

/**
 * Get initials from name
 * @param {string} name - Full name
 * @returns {string} Initials (e.g., "John Doe" -> "JD")
 */
export function getInitials(name) {
	if (!name) return '';
	const parts = name.trim().split(' ');
	if (parts.length === 1) return parts[0].charAt(0).toUpperCase();
	return (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase();
}

/**
 * Format relative time (e.g., "2 hours ago")
 * @param {string|Date} date - Date to format
 * @returns {string} Relative time string
 */
export function formatRelativeTime(date) {
	if (!date) return '';
	return frappe.datetime.comment_when(date);
}

/**
 * Format file size
 * @param {number} bytes - File size in bytes
 * @returns {string} Formatted file size
 */
export function formatFileSize(bytes) {
	if (!bytes) return '0 B';

	const sizes = ['B', 'KB', 'MB', 'GB'];
	const i = Math.floor(Math.log(bytes) / Math.log(1024));
	return `${(bytes / Math.pow(1024, i)).toFixed(2)} ${sizes[i]}`;
}

/**
 * Capitalize first letter of each word
 * @param {string} text - Text to capitalize
 * @returns {string} Capitalized text
 */
export function capitalizeWords(text) {
	if (!text) return '';
	return text.replace(/\b\w/g, char => char.toUpperCase());
}

/**
 * Format status badge HTML
 * @param {string} status - Status text
 * @param {string} color - Color indicator
 * @returns {string} HTML string for status badge
 */
export function formatStatusBadge(status, color = 'blue') {
	return `<span class="indicator-pill ${color}">${status}</span>`;
}
"}

