}

// Card responsive
.card-responsive {
	@media (max-width: $breakpoint-md) {
		margin-bottom: 12px;
		padding: 12px;
	}

	@media (max-width: $breakpoint-sm) {
		margin-bottom: 8px;
		padding: 10px;
	}
}
